import { Box, Flex, IconButton, Text } from "@chakra-ui/react";
import React, { forwardRef } from "react";
import { Icon } from "../../../Icon";
import { Brain, ChevronDown, ChevronUp } from "../../../Icon/icons";
import type { ConversationEvent, ConversationEventAction } from "../../../types";
import { deriveLlmCallView } from "../../deriveLlmCallView";
import { ConversationEventActionButton } from "../../ConversationEventActionButton";
import { useConversationLogSx } from "../useConversationLogSx";
import { ErrorDot } from "./ErrorDot";

interface LlmCallEventProps {
  event: ConversationEvent;
  isSelected: boolean;
  conversationEventActions?: ConversationEventAction[];
  onClick?: React.MouseEventHandler<HTMLDivElement>;
  onKeyDown?: (e: React.KeyboardEvent<HTMLDivElement>) => void;
  /** Set when the row heads a group of resulting events (chevron toggle). */
  expanded?: boolean;
  onToggleExpand?: () => void;
}

/** Log row for one LLM completion; details open in the event panel. */
export const LlmCallEvent = forwardRef<HTMLDivElement | null, LlmCallEventProps>(
  (props: LlmCallEventProps, ref) => {
    const {
      event,
      isSelected = false,
      conversationEventActions,
      onClick,
      onKeyDown,
      expanded,
      onToggleExpand,
      ...otherProps
    } = props;
    const { hoverableContainerSx, baseMessageSx, iconSx } = useConversationLogSx(isSelected);
    const [isHovered, setIsHovered] = React.useState(false);

    const record = event.metadata?.llm_call;
    if (!record) return null;
    const view = deriveLlmCallView(record);

    return (
      <Flex
        ref={ref}
        tabIndex={0}
        role="button"
        position="relative"
        cursor="pointer"
        css={hoverableContainerSx}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        onClick={onClick}
        onKeyDown={onKeyDown}
        data-testid="llm-call-event"
        {...otherProps}
      >
        {isHovered && (
          <ConversationEventActionButton event={event} actions={conversationEventActions} />
        )}
        <Box css={baseMessageSx}>
          <Icon icon={Brain} style={iconSx} />
          <Text textStyle="xs" lineClamp={2} wordBreak="break-all" variant="muted">
            LLM call{" "}
            <Text as="span" fontWeight="medium" variant="muted">
              {view.model}
            </Text>
            {view.durationLabel ? ` · ${view.durationLabel}` : ""}
            {view.purpose ? ` · ${view.purpose}` : ""}
          </Text>
          {view.isError && <ErrorDot />}
          {onToggleExpand ? (
            <IconButton
              aria-label={expanded ? "Collapse LLM call events" : "Expand LLM call events"}
              size="2xs"
              variant="ghost"
              colorPalette="gray"
              data-testid="llm-call-toggle"
              onClick={(clickEvent) => {
                clickEvent.stopPropagation();
                onToggleExpand();
              }}
            >
              <Icon icon={expanded ? ChevronUp : ChevronDown} size="sm" />
            </IconButton>
          ) : null}
        </Box>
      </Flex>
    );
  },
);
